SELECT g.id, g.name_original, g.confidence_score, (SELECT count(*) FROM sources s WHERE s.entity_id=g.id) AS n_src FROM geo_entities g WHERE g.id IN (367, 574, 578, 581, 655, 889, 904, 958, 983, 1015) ORDER BY g.id;
